cat > /tmp/edit.py <<'EOF'
p='src/statement.mjs'
s=open(p).read()
i=s.index('/**\n * The monthly usage')
head=s[:i]
new='''/** Share of the whole as a percentage to one decimal, rounded half up, from whole cents. */
function percent(part, whole) {
  if (whole === 0) return "0.0%";
  const tenths = Math.floor((part * 2000 + whole) / (2 * whole));
  return `${Math.trunc(tenths / 10)}.${tenths % 10}%`;
}

/** "A", "A and B", "A, B and C". */
function listNames(names) {
  if (names.length <= 1) return names.join("");
  return `${names.slice(0, -1).join(", ")} and ${names[names.length - 1]}`;
}

/** Greedy word wrap to at most `width` characters per line. */
function wrap(text, width) {
  const lines = [];
  let line = "";
  for (const word of text.split(" ")) {
    if (line && line.length + 1 + word.length > width) {
      lines.push(line);
      line = word;
    } else {
      line = line ? `${line} ${word}` : word;
    }
  }
  if (line) lines.push(line);
  return lines;
}

/**
 * The monthly usage statement as plain text.
 * @param {{ customer: string, account: string, period: string, currency: string,
 *           lines: { service: string, quantity: number, unit: string, amount_cents: number }[],
 *           credits: { reason: string, amount_cents: number }[] }} data
 * @returns {string}
 */
export function renderStatement(data) {
  const unused = data.lines
    .filter((l) => l.quantity === 0 && l.amount_cents === 0)
    .sort((a, b) => a.service.localeCompare(b.service));
  // Used services only, largest charge first; equal amounts by name.
  const used = data.lines
    .filter((l) => !(l.quantity === 0 && l.amount_cents === 0))
    .sort((a, b) => b.amount_cents - a.amount_cents || a.service.localeCompare(b.service));
  const credits = [...data.credits].sort(
    (a, b) => Math.abs(b.amount_cents) - Math.abs(a.amount_cents) || a.reason.localeCompare(b.reason),
  );

  const charges = data.lines.reduce((sum, l) => sum + l.amount_cents, 0);
  const creditsSum = data.credits.reduce((sum, c) => sum + c.amount_cents, 0);
  const total = charges + creditsSum;

  // Credits are shown as positive figures in parentheses; the closing
  // parenthesis sits in a one-character slot after the amount column.
  const usageOf = (l) => `${groupDigits(l.quantity)} ${l.unit}`;
  const serviceW = Math.max("Service".length, ...used.map((l) => l.service.length));
  const usageW = Math.max("Usage".length, ...used.map((l) => usageOf(l).length));
  const shareW = Math.max("Share".length, "100.0%".length);
  const amountW = Math.max(
    `Amount (${data.currency})`.length,
    ...used.map((l) => money(l.amount_cents).length),
    ...credits.map((c) => money(Math.abs(c.amount_cents)).length),
    money(charges).length,
    money(total).length,
  );
  const slot = 1;
  const gap = "  ";
  const width = serviceW + usageW + shareW + amountW + slot + gap.length * 3;
  const rule = "-".repeat(width);
  const trim = (s) => s.replace(/\\s+$/, "");

  const row = (a, b, c, d, tail = " ") =>
    trim(
      [padRight(a, serviceW), padRight(b, usageW), padLeft(c, shareW), padLeft(d, amountW)].join(gap) + tail,
    );
  // A label on the left and an amount flush with the amount column.
  const summary = (label, text, tail = " ") =>
    trim(`${padRight(label, width - amountW - slot - gap.length)}${gap}${padLeft(text, amountW)}${tail}`);

  const out = [];
  const account = `Account ${data.account}`;
  out.push(`${padRight(data.customer, Math.max(1, width - account.length))}${account}`);
  out.push(`Usage statement for ${monthName(data.period)}`);
  out.push("");
  out.push(row("Service", "Usage", "Share", `Amount (${data.currency})`));
  out.push(rule);
  for (const l of used) {
    out.push(row(l.service, usageOf(l), percent(l.amount_cents, charges), money(l.amount_cents)));
  }
  out.push(rule);
  out.push(row("Charges", "", percent(charges, charges), money(charges)));
  out.push("");
  out.push("Credits");
  for (const c of credits) {
    const cents = c.amount_cents;
    // Credits are stored as negative amounts; a positive adjustment would be shown plain.
    out.push(summary(`  ${c.reason}`, cents < 0 ? money(-cents) : money(cents), cents < 0 ? ")" : " "));
  }
  out.push(rule);
  out.push(summary("Total due", money(total)));
  if (unused.length > 0) {
    const n = unused.length;
    out.push("");
    out.push(
      ...wrap(
        `${n} ${n === 1 ? "service" : "services"} with no usage ${n === 1 ? "is" : "are"} not listed: ${listNames(unused.map((l) => l.service))}.`,
        width,
      ),
    );
  }
  return `${out.join("\\n")}\\n`;
}
'''
open(p,'w').write(head+new)
